from __future__ import annotations

import os
import sys
import shutil
import urllib.request
import zipfile
import subprocess
import tempfile
from pathlib import Path

MT5_APP = "/Applications/MetaTrader 5.app"
WINE_BIN = f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine64"
if not os.path.exists(WINE_BIN) and os.path.exists(f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine"):
    WINE_BIN = f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine"
DEFAULT_WINEPREFIX = os.path.expanduser(
    "~/Library/Application Support/net.metaquotes.wine.metatrader5")
DEFAULT_PYTHON = "C:\\Python39\\python.exe"

PYTHON_VERSION = "3.9.13"
PYTHON_URL = (
    f"https://www.python.org/ftp/python/{PYTHON_VERSION}/"
    f"python-{PYTHON_VERSION}-embed-amd64.zip"
)
GET_PIP_URL = "https://bootstrap.pypa.io/pip/3.9/get-pip.py"


class BootstrapError(Exception):
    pass


def ensure_environment(
    wine_bin: str = WINE_BIN,
    wineprefix: str = "",
    python_path: str = DEFAULT_PYTHON,
    verbose: bool = True,
) -> bool:
    """Ensure the Wine Python environment with MetaTrader5 is ready.

    Returns True if environment is ready, False if something critical
    is missing (e.g. MT5.app not installed).
    """
    _log = lambda msg: print(f"[mt5_mac] {msg}") if verbose else None

    if not os.path.exists(wine_bin):
        raise BootstrapError(
            f"MetaTrader 5.app not found at {MT5_APP}.\n"
            "Please install MetaTrader 5 for macOS from "
            "https://www.metatrader5.com/en/download"
        )

    wineprefix = wineprefix or os.environ.get("WINEPREFIX", DEFAULT_WINEPREFIX)
    python_exe = os.path.join(wineprefix, "drive_c", "Python39", "python.exe")
    python_exe_wine = python_path

    python_dir = os.path.dirname(python_exe)

    if not os.path.exists(python_exe):
        _log(f"Wine Python not found. Downloading Python {PYTHON_VERSION}...")
        _install_python_embeddable(wine_bin, wineprefix, python_exe)
        _log("Python installed.")

    _enable_site_packages(python_dir)

    if not _check_pip_installed(wine_bin, wineprefix, python_exe_wine):
        _log("pip not found in Wine Python. Installing pip...")
        _install_pip(wine_bin, wineprefix, python_dir)
        _log("pip installed.")

    if not _check_mt5_installed(wine_bin, wineprefix, python_exe_wine):
        _log("MetaTrader5 package not found. Installing...")
        _install_mt5_package(wine_bin, wineprefix, python_exe_wine)
        _log("MetaTrader5 package installed.")

    return True


def _enable_site_packages(python_dir: str) -> None:
    _pth_file = os.path.join(python_dir, "python39._pth")
    if os.path.exists(_pth_file):
        with open(_pth_file, "r") as f:
            content = f.read()
        modified = False
        if "#import site" in content:
            content = content.replace("#import site", "import site")
            modified = True
        elif "import site" not in content:
            content = content.rstrip() + "\nimport site\n"
            modified = True
        if modified:
            with open(_pth_file, "w") as f:
                f.write(content)


def _check_pip_installed(
    wine_bin: str,
    wineprefix: str,
    python_exe_wine: str,
) -> bool:
    env = {**os.environ, "WINEPREFIX": wineprefix}
    result = subprocess.run(
        [wine_bin, python_exe_wine, "-m", "pip", "--version"],
        capture_output=True, text=True, env=env,
    )
    return result.returncode == 0


def _install_pip(
    wine_bin: str,
    wineprefix: str,
    python_dir: str,
) -> None:
    pip_script_path = os.path.join(python_dir, "get-pip.py")
    if os.path.exists(pip_script_path):
        try:
            os.remove(pip_script_path)
        except Exception:
            pass
    print("  Downloading pip for Python 3.9...")
    try:
        _download(GET_PIP_URL, pip_script_path, "get-pip.py")
    except Exception as e:
        raise BootstrapError(f"Failed to download get-pip.py: {e}")

    print("  Installing pip...")
    env = {**os.environ, "WINEPREFIX": wineprefix}
    result = subprocess.run(
        [wine_bin, "C:\\Python39\\python.exe", "C:\\Python39\\get-pip.py"],
        capture_output=True, text=True, env=env,
    )
    if result.returncode != 0:
        raise BootstrapError(
            f"Failed to install pip (exit code {result.returncode}):\n"
            f"STDOUT:\n{result.stdout}\n"
            f"STDERR:\n{result.stderr}\n"
        )

    if os.path.exists(pip_script_path):
        os.remove(pip_script_path)


def _install_python_embeddable(
    wine_bin: str,
    wineprefix: str,
    python_exe: str,
) -> None:
    python_dir = os.path.dirname(python_exe)
    os.makedirs(python_dir, exist_ok=True)

    with tempfile.TemporaryDirectory() as tmpdir:
        zip_path = os.path.join(tmpdir, "python.zip")
        try:
            _download(PYTHON_URL, zip_path, "Python embeddable package")
        except Exception as e:
            raise BootstrapError(
                f"Failed to download Python {PYTHON_VERSION}: {e}\n"
                "Please check your internet connection."
            )

        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(python_dir)

    _enable_site_packages(python_dir)
    _install_pip(wine_bin, wineprefix, python_dir)


def _install_mt5_package(
    wine_bin: str,
    wineprefix: str,
    python_exe_wine: str,
) -> None:
    env = {**os.environ, "WINEPREFIX": wineprefix}
    try:
        result = subprocess.run(
            [wine_bin, python_exe_wine, "-m", "pip", "install", "MetaTrader5"],
            capture_output=True, text=True, env=env,
            timeout=120,
        )
    except subprocess.TimeoutExpired:
        raise BootstrapError(
            "Timed out installing MetaTrader5 package (120s).\n"
            "Please check your internet connection and try again."
        )
    if result.returncode != 0:
        raise BootstrapError(
            f"Failed to install MetaTrader5 package:\n"
            f"{result.stderr[:500]}\n{result.stdout[:500]}"
        )


def _check_mt5_installed(
    wine_bin: str,
    wineprefix: str,
    python_exe_wine: str,
) -> bool:
    env = {**os.environ, "WINEPREFIX": wineprefix}
    result = subprocess.run(
        [wine_bin, python_exe_wine, "-c", "import MetaTrader5; print('ok')"],
        capture_output=True, text=True, env=env,
    )
    return result.returncode == 0 and result.stdout.strip() == "ok"


def _download(url: str, dest: str, label: str = "") -> None:
    def _report(block: int, blocksize: int, totalsize: int):
        if block % 50 == 0:
            downloaded = block * blocksize
            if totalsize > 0:
                pct = min(100, downloaded * 100 / totalsize)
                print(f"\r  Downloading {label}... {pct:.0f}%  ", end="", flush=True)
            else:
                print(f"\r  Downloading {label}... {_format_size(downloaded)}  ", end="", flush=True)

    urllib.request.urlretrieve(url, dest, _report)
    print(f"\r  Downloaded {label} ({_format_size(os.path.getsize(dest))})")


def _format_size(size: int) -> str:
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024:
            return f"{size:.1f} {unit}"
        size /= 1024
    return f"{size:.1f} TB"
